{"results": [{"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 1.37, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-009 (0.78)"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF17", "label": "Study family SF17: Wiring confirmatory: persistence (P1a) and irreducibility to play-type rates (P1b)", "score": 1.041, "reached_via": ["request matches the question or hypothesis of FAM:SF17 (0.73)", "request matches RQC:RQC-011 (0.71); FAM:SF17 auto_addresses_question RQC:RQC-011"], "attributes": {"observed_research_question": "Wiring confirmatory: persistence (P1a) and irreducibility to play-type rates (P1b)", "auto_outcome_status": "supported", "observed_hypothesis": "Team offensive association structure is more similar to itself across split halves than to other teams, even after residualizing play-type rates.", "observed_result": ["[APPS-080] Gate: C1 8/8 p<0.05; C2 S=0.319 perm_p=0.0002; C3 R2=0.080 PASS. Full: frobenius P1a S=0.352 p=0.0000 CI[0.327,0.378]; P1b S=0.353 CI[0.329,0.379]; cosine P1a 0.155 / P1b 0.144. residual_R2=0.043. D_obs mean=3 [cut; read_family for the full text]", "[CHT-049] Residual R^2=0.043. Frobenius P1a S=0.352 p=0.0000 CI [0.327, 0.378]; P1b S=0.353 [0.329, 0.379]. Cosine P1a S=0.155 [0.132, 0.179]; P1b S=0.144 [0.123, 0.170]. All p<0.01."], "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "[CHT-049] NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-PAP-001"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 0.879, "reached_via": ["FAM:SF-APPM-022 auto_related_family (repeated_by_later_family) FAM:SF-APPA-050", "FAM:SF-APPM-022 auto_related_family (repeat_of_earlier_family) FAM:SF-APPA-050"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 0.879, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-022 (0.75)", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.77); FAM:SF-APPM-022 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result": "Q5c verdict 'rank-1 suppressor varies meaningfully across players'; e.g. Jokic after opp POST_UP 1.1271 (-0.0675, SE +/-0.0500, n=480); Curry forced POST_UP -0.209.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in doc.", "observed_sample_and_power": "SE per cell reported", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-050"}]}, {"id": "FAM:SF-APPA-017", "label": "Study family SF-APPA-017: A5 player-routing and A5b defensive attention penalty", "score": 0.858, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-017 (0.73)", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.77); FAM:SF-APPA-017 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "A5 player-routing and A5b defensive attention penalty", "auto_outcome_status": "rejected", "observed_hypothesis": "Routing possessions to each play type's best player adds value over A3, and survives defensive attention adaptation.", "observed_result": "V4 A5 vs A3 +0.77; V5 +0.94 (A5b vs A5 +0.01); V6 (520 matchups) A5 vs A3 +0.03, A5b vs A5 -0.00.", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Shrinks from +0.94 to +0.03 pts/100 on the larger 520-matchup sample.", "observed_sample_and_power": "520 matchups", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Calibration framework V4-V6; A5 vs A3 and A5b vs A5 signal in pts/100.", "observed_verdict": "null", "observed_failure_type": "B_powered_null", "observed_notes": "Model-scored, not observed outcomes.", "auto_confidence": "high (0.95)"}, "relationships": [{"rel": "auto_addresses_question", "node": "RQC:RQC-012"}]}, {"id": "FAM:SF18", "label": "Study family SF18: Fragility confirmatory: F1a usage decoupling and F1b split-half stability of residual influence", "score": 0.674, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF18", "request matches RQC:RQC-011 (0.71); FAM:SF18 auto_addresses_question RQC:RQC-011"], "attributes": {"observed_research_question": "Fragility confirmatory: F1a usage decoupling and F1b split-half stability of residual influence", "auto_outcome_status": "supported", "observed_hypothesis": "Structural influence is not reducible to usage and the usage-residual is a reproducible player property.", "observed_result": ["[APPA-039] F1a cosine R2=0.094, residual-share=0.906, CI [0.768, 0.962] PASS; Frobenius R2=0.073 share=0.927 CI [0.828, 0.965]. F1b pooled-residual rho=+0.685 p=0.0000 CI [+0.649, +0.721]; usage-partial rho=+0.557 p=0.00 [cut; read_family for the full text]", "[APPS-083] F1a cosine R2=0.099 share=0.901 CI[0.778,0.954]; frobenius R2=0.084 share=0.916. F1b pooled rho=+0.670 p=0.0000 CI[+0.636,+0.705]; partial rho=+0.560 CI[+0.496,+0.616]. F1a=CONFIRMED F1b=CONFIRMED."], "auto_failure_mechanism": "D_positive (no failure: positive result)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:low_measurement_reliability"}, {"rel": "auto_has_risk", "node": "RISK:MEASURE_RELIABILITY"}]}, {"id": "FAM:SF20", "label": "Study family SF20: Absence validation (structure moves under real absence; simulation tracks it)", "score": 0.674, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF20", "request matches RQC:RQC-011 (0.71); FAM:SF20 auto_addresses_question RQC:RQC-011"], "attributes": {"observed_research_question": "Absence validation (structure moves under real absence; simulation tracks it)", "auto_outcome_status": "untestable", "observed_hypothesis": "Real player absences move the association structure (V1) and the LOO simulation predicts the magnitude (V2).", "observed_result": ["[APPA-006] Gate G2 21/23 (91%) above null median; V1(a) 16/23 above own-null p95, binomial p=2.67e-16; V1(b) mean(D_real - median_null)=+0.142, CI [+0.103, +0.187].", "[APPA-007] Gate G3 Spearman +0.099. V2a Spearman +0.288, p=0.077, CI [-0.244, +0.667] FAIL; V2b partial +0.253, p=0.115, CI [-0.262, +0.615] FAIL. Diagnostics: H_code ruled out (rho=0.933); dropping 2 absorption cases rh [cut; read_family for the full text]", "[PAP-023] V1(a) 16/23 above p95 binomial p=2.67e-16; V1(b) +0.142 CI[+0.103,+0.187] CONFIRMED; V2a rho=+0.288 p=0.077 CI[-0.244,+0.667]; V2b rho=+0.253 p=0.115 NOT"]}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}]}, {"id": "FAM:SF-APPA-066", "label": "Study family SF-APPA-066: TOV_FORCE matchup decomposition on four playoff games", "score": 0.567, "reached_via": ["request matches RQC:RQC-066 (0.70); FAM:SF-APPA-066 auto_addresses_question RQC:RQC-066", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.77); FAM:SF-APPA-066 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "TOV_FORCE matchup decomposition on four playoff games", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "TOV_FORCE as a top-3 lever can be decomposed into defender x initiator x PT channels with positive matchup lift.", "observed_result": "Team-PT lifts are small (ORL vs DET PNR +1.2pp; POR vs SAS all PT lifts negative, e.g. PNR -4.1pp) while player-channel lifts are large on small n (Banchero on Huerter SPOT_UP +8.4pp, n_def=17 / n_off=54; Dort on Coffey  [cut; read_family for the full text]", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Player-channel n often 15-28 defensive possessions; primary_defender attribution includes helper steals; no holdout or game-outcome check.", "observed_sample_and_power": "4 games; cell n often 15-54"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:insufficient_exposure"}, {"rel": "auto_has_risk", "node": "RISK:EXPOSURE_SPARSITY"}]}, {"id": "FAM:SF-APPS-059", "label": "Study family SF-APPS-059: Sequence-memory horizon test (per-lag vs aggregated window)", "score": 0.493, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF-APPS-059", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.77); FAM:SF-APPS-059 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Sequence-memory horizon test (per-lag vs aggregated window)", "auto_outcome_status": "supported", "observed_hypothesis": "Increasing prior-possession history changes the opponent's next-possession outcome after controlling for game state.", "observed_result": "Per-lag GBT AUC N=0 0.5621 -> N=1 0.5863 (d+0.0242) -> N=3 0.5907 -> N=8 0.5911. R2 0.0051 -> 0.0133. Aggregated window declines after N=1 (AUC 0.5868 -> 0.5687 at N=8). Effective horizon ~2-3 possessions.", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Short-memory horizon is stable OOS; almost all gain is lag-1, plateau by lag 4. Absolute AUC still only ~0.591.", "observed_sample_and_power": "n=1,024,980 possessions; time-split test 2025-26", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-070"}, {"rel": "auto_related_family", "node": "FAM:SF17"}]}, {"id": "FAM:SF-APPM-054", "label": "Study family SF-APPM-054: Playoff adaptation-pair sustainability (12 pairs x 74 matchups)", "score": 0.476, "reached_via": ["request matches RQC:RQC-029 (0.70); FAM:SF-APPM-054 auto_addresses_question RQC:RQC-029", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.77); FAM:SF-APPM-054 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Playoff adaptation-pair sustainability (12 pairs x 74 matchups)", "auto_outcome_status": "rejected", "observed_hypothesis": "Pivoting to a listed counter after suppression sustains higher PPP than not pivoting, consistently across playoff matchups.", "observed_result": "10/12 pairs CONSISTENT and within 0.10 of non-pivot (no PIVOT_WINS). PNR->PULL_UP sustained 1.069 vs non_pivot 1.224 (n_matchups=9) PIVOT_LOSES. DRIVE->PULL_UP 1.101 vs 1.217 (n=5) PIVOT_LOSES. Largest positive pair in t [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Population deltas mostly |d|<0.10; two pairs with enough signal are PIVOT_LOSES (pivot worse than staying).", "observed_sample_and_power": "n=74 matchups; pair n_matchups 5 to 44"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPM-033"}]}], "n_results": 10}

